include!("../../../src/OpenGMK/gm8emulator/src/ios/archive.rs");
mod saves { include!("../../../src/OpenGMK/gm8emulator/src/ios/saves.rs"); }
#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;
    fn temp()->PathBuf {static N:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let p=std::env::temp_dir().join(format!("reload-ios-{}-{}",std::process::id(),N.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));fs::create_dir_all(&p).unwrap();p}
    fn zip_at(dir:&Path,entries:&[(&str,&[u8])])->PathBuf {let path=dir.join("input.zip");let mut z=zip::ZipWriter::new(fs::File::create(&path).unwrap());for (name,data)in entries{z.start_file(*name,zip::write::SimpleFileOptions::default()).unwrap();z.write_all(data).unwrap();}z.finish().unwrap();path}
    #[test]fn imports_nested_game(){let d=temp();let z=zip_at(&d,&[("release/Reloaded.exe",b"MZ"),("release/data/test.txt",b"ok")]);let out=d.join("game");extract(&z,&out).unwrap();assert_eq!(find_exe(&out).unwrap(),out.join("release/Reloaded.exe"));fs::remove_dir_all(d).unwrap();}
    #[test]fn rejects_traversal_and_cleans_staging(){let d=temp();let z=zip_at(&d,&[("../escape",b"bad")]);let out=d.join("game");assert!(extract(&z,&out).is_err());assert!(!d.join("escape").exists());assert!(!out.with_extension("importing").exists());fs::remove_dir_all(d).unwrap();}
    #[test]fn preserves_existing_save(){let d=temp();let out=d.join("game");fs::create_dir(&out).unwrap();fs::write(out.join("save.sav"),b"original").unwrap();let z=zip_at(&d,&[("Reloaded.exe",b"MZ"),("data/test",b"x")]);assert!(extract(&z,&out).is_err());assert_eq!(fs::read(out.join("save.sav")).unwrap(),b"original");fs::remove_dir_all(d).unwrap();}
    #[test]fn rejects_non_game_without_installing(){let d=temp();let z=zip_at(&d,&[("note.txt",b"none")]);let out=d.join("game");assert!(extract(&z,&out).is_err());assert!(!out.exists());fs::remove_dir_all(d).unwrap();}
    #[test]fn rejects_windows_traversal(){let d=temp();let z=zip_at(&d,&[("..\\escape",b"bad")]);assert!(extract(&z,&d.join("game")).is_err());assert!(!d.join("escape").exists());fs::remove_dir_all(d).unwrap();}
    #[test]fn save_roundtrip_and_slot_transfer(){let d=temp();let data=d.join("data");fs::create_dir_all(data.join("partidas")).unwrap();fs::create_dir_all(data.join("equipos")).unwrap();fs::write(data.join("partidas/reloaded1.savc"),b"SAVE").unwrap();fs::write(data.join("equipos/team.dat"),b"TEAM").unwrap();let z=d.join("all.zip");saves::export(&data,&z,0).unwrap();let other=d.join("other");fs::create_dir(&other).unwrap();assert_eq!(saves::import(&other,&z,0).unwrap(),2);assert_eq!(fs::read(other.join("equipos/team.dat")).unwrap(),b"TEAM");let slot=d.join("slot.zip");saves::export(&data,&slot,1).unwrap();saves::import(&other,&slot,3).unwrap();assert_eq!(fs::read(other.join("partidas/reloaded3.savc")).unwrap(),b"SAVE");assert_eq!(fs::read(other.join("partidas/reloaded1.savc")).unwrap(),b"SAVE");fs::remove_dir_all(d).unwrap();}
    #[test]fn rejected_save_zip_preserves_everything(){let d=temp();let data=d.join("data");fs::create_dir_all(data.join("partidas")).unwrap();fs::write(data.join("partidas/reloaded1.savc"),b"ORIGINAL").unwrap();let z=zip_at(&d,&[("partidas/reloaded1.savc",b"NEW"),("partidas/../../escape",b"BAD")]);assert!(saves::import(&data,&z,0).is_err());assert_eq!(fs::read(data.join("partidas/reloaded1.savc")).unwrap(),b"ORIGINAL");assert!(!d.join("escape").exists());fs::remove_dir_all(d).unwrap();}
    #[test]fn interrupted_save_commit_rolls_back(){let d=temp();let data=d.join("data");let journal=data.join(".save-import");fs::create_dir_all(journal.join("old-partidas")).unwrap();fs::write(journal.join("old-partidas/reloaded1.savc"),b"OLD").unwrap();fs::create_dir(data.join("partidas")).unwrap();fs::write(data.join("partidas/reloaded1.savc"),b"NEW").unwrap();fs::write(journal.join("started"),b"").unwrap();saves::recover(&data).unwrap();assert_eq!(fs::read(data.join("partidas/reloaded1.savc")).unwrap(),b"OLD");assert!(!journal.exists());fs::remove_dir_all(d).unwrap();}
    #[test]fn ambiguous_slot_import_is_rejected(){let d=temp();let data=d.join("data");fs::create_dir(&data).unwrap();let z=zip_at(&d,&[("partidas/reloaded1.savc",b"A"),("partidas/reloaded2.savc",b"B")]);assert!(saves::import(&data,&z,3).is_err());assert!(!data.join("partidas").exists());fs::remove_dir_all(d).unwrap();}
}
